void strict_wire_rejection_and_legacy_migration()
{
    begin("strict_wire_rejection_and_legacy_migration");
    juce::MemoryBlock sound; CHECK(encodeSoundState(rich().sound, sound));
    const auto valid = envelope(bytes(sound), literalPattern(), 1);
    for (std::size_t size = 0; size < valid.size(); ++size) rejects(valid.data(), size);
    for (std::size_t i = 0; i < valid.size(); ++i) { auto b = valid; b[i] ^= 1; rejects(b); }
    // Header admission must reject even when outer integrity has been recomputed.
    for (std::size_t i = 0; i < 20; ++i)
    {
        auto b = valid; b[i] ^= (i == 8 ? 2 : 1); sign(b); rejects(b);
    }
    for (const auto length : {0U, 55U, 57U, 93U, 95U, 4921U, 0xffffffffU})
    { auto b = valid; put(b, 16, length, 4); sign(b); rejects(b); }
    for (const auto length : {0U, 1720U, 7006U, 7023U, 7025U, 0xffffffffU})
    { auto b = valid; put(b, 12, length, 4); sign(b); rejects(b); }
    rejects(nullptr, 0); rejects(nullptr, valid.size()); rejects(valid.data(), std::numeric_limits<std::size_t>::max());
    auto b = valid; b.push_back(0); rejects(b); sign(b); rejects(b);
    b.resize(11997, 0); rejects(b);
    auto alias = rich(); const auto beforeAlias = alias;
    rejects(&alias, 0); CHECK(!decodeProjectState(&alias, currentMinimumProjectStateBytes, alias)); CHECK(exact(alias, beforeAlias));
    // Valid outer digest cannot hide a bad nested digest or nested semantic corruption.
    b = valid; b[20 + currentSoundStateSize-1] ^= 1; sign(b); rejects(b);
    b = valid; b[currentPatternOffset + 93] ^= 1; sign(b); rejects(b);
    for (const std::size_t offset : std::array<std::size_t, 11>{0, 4, 6, 8, 9, 10, 11, 20, 21, 22, 23})
    {
        b = valid; b[currentPatternOffset + offset] = 255; signRange(b, currentPatternOffset, 94); sign(b); rejects(b);
    }
    for (const auto bits : {0x7ff8000000000000ULL, 0x7ff0000000000000ULL, 0xbff0000000000000ULL, 0x4000000000000000ULL})
    { b = valid; put(b, currentPatternOffset+12, bits, 8); signRange(b, currentPatternOffset, 94); sign(b); rejects(b); }
    for (const auto bits : {0x7ff8000000000000ULL, 0x7ff0000000000000ULL, 0xbff0000000000000ULL, 0x4020000000000000ULL})
    { b = valid; put(b, currentPatternOffset+24, bits, 8); signRange(b, currentPatternOffset, 94); sign(b); rejects(b); }
    for (const auto bits : {0ULL, 0x7ff8000000000000ULL, 0x7ff0000000000000ULL, 0xbff0000000000000ULL, 0x4020000000000000ULL})
    { b = valid; put(b, currentPatternOffset+32, bits, 8); signRange(b, currentPatternOffset, 94); sign(b); rejects(b); }
    for (const auto field : {std::pair<std::size_t,int>{currentPatternOffset+40,128}, {currentPatternOffset+41,0}, {currentPatternOffset+41,128}, {currentPatternOffset+42,0}, {currentPatternOffset+42,17}})
    { b = valid; b[field.first] = static_cast<std::uint8_t>(field.second); signRange(b, currentPatternOffset, 94); sign(b); rejects(b); }
    for (const auto field : {std::pair<std::size_t,std::uint32_t>{20,0}, {24,2}, {28,756}, {32,1}, {36,0}, {40,0x7fc00000}, {40,0x40000000}})
    { b = valid; put(b, field.first, field.second, 4); signRange(b, 20, currentSoundStateSize); sign(b); rejects(b); }
    // A legacy sound nested in a valid AIPJ is forbidden, even with accurate lengths/digests.
    struct Legacy { const char* path; std::size_t size; int version; const char* hash; };
    const Legacy fixtures[] {
        {"tests/fixtures/m1-analog-pluck.soundstate",1720,1,"6fbc457ffb3bbd821a458244aa5135857b5356c946a16924b3c494ad529698f4"},
        {"tests/fixtures/m2-analog-pluck.v2.soundstate",7006,2,"2f1dbdb7219055a9e7e90b655e2e50b2a33c11b48932af116373215807adea19"},
        {"tests/fixtures/m2-calibrated-pluck.v3.soundstate",7024,3,"6f15139e4dc680f914c16458a06221358ab94613458cb88336167eb6b9272a08"}
    };
    for (const auto& fixture : fixtures)
    {
        const auto raw = load(fixture.path, fixture.size, fixture.hash);
        const auto legacy = bytes(raw);
        CHECK(legacy.size() == fixture.size);
        if (legacy.size() != fixture.size) continue;
        CHECK(legacy[4] == fixture.version);
        SoundDocument expected; CHECK(decodeSoundState(raw.getData(), raw.getSize(), expected));
        // The expected sound comes directly from retained native bytes, never re-encoded.
        auto out = rich(); CHECK(decodeProjectState(raw.getData(), raw.getSize(), out));
        ProjectDocument want; want.sound = expected;
        CHECK(exact(out, want)); CHECK(out.pattern.noteCount == 0); CHECK(out.mode == PlaybackMode::externalMidi);
        if (fixture.version < 3) { CHECK(out.sound.values[756] == .4f); CHECK(out.sound.values[757] == 0); }
        juce::MemoryBlock upgraded; CHECK(encodeProjectState(out, upgraded)); CHECK(upgraded.getSize() == currentMinimumProjectStateBytes);
        if (upgraded.getSize() == currentMinimumProjectStateBytes) { const auto upgradedBytes = bytes(upgraded); CHECK(upgradedBytes[0] == 'A' && upgradedBytes[3] == 'J'); }
        auto nested = envelope(legacy, literalPattern(), 1);
        if (fixture.version < 3) rejects(nested);
        else { out = {}; want.pattern = rich().pattern; want.mode = PlaybackMode::internalPattern;
               CHECK(decodeProjectState(nested.data(), nested.size(), out)); CHECK(exact(out, want)); }
        for (std::size_t i = 0; i < legacy.size(); ++i) { auto corrupt = legacy; corrupt[i] ^= 1; rejects(corrupt); }
        auto corrupt = legacy; put(corrupt, 12, 1, 4); sign(corrupt); rejects(corrupt);
        corrupt = legacy; put(corrupt, 20, 0x7fc00000, 4); sign(corrupt); rejects(corrupt);
        corrupt = legacy; corrupt.push_back(0); rejects(corrupt);
        rejects(legacy.data(), legacy.size() - 1);
    }
    // Asset codecs are strict independent boundaries; a whole project is neither asset.
    PatternDocument pattern; const auto beforePattern = pattern;
    CHECK(!decodePatternAsset(valid.data(), valid.size(), pattern)); CHECK(pattern == beforePattern);
    SoundDocument soundOut; const auto beforeSound = soundOut;
    CHECK(!decodeSoundState(valid.data(), valid.size(), soundOut)); CHECK(soundOut == beforeSound);
}
