void groupRejects(const void* data,std::size_t size)
{
    static const auto baseline=[]
    {
        const auto value=grouped();const auto fresh=grouped();
        CHECK(exact(value,fresh));
        CHECK(value.sound.name.isEmpty()&&fresh.sound.name.isEmpty());
        CHECK(!value.sound.personalities&&!fresh.sound.personalities);
        auto changed=value;
        changed.sound.values[1]=1.0f;changed.sound.values[2]=2.0f;
        changed.sound.name="changed";
        changed.group->name=literalText("changed");changed.group->bpm=200.0;
        changed.pattern.notes[0].startBeats=1.0;changed.pattern.notes[0].durationBeats=2.0;
        CHECK(!exact(changed,value));
        CHECK(exact(value,fresh));
        const auto next=value;CHECK(exact(next,fresh));
        return value;
    }();
    auto output=baseline;const auto before=output;
    CHECK(!decodeProjectState(data,size,output));CHECK(exact(output,before));
}
void groupRejects(const Bytes& b){groupRejects(b.data(),b.size());}
