    for(const auto revision:revisions){state->instances[0].design.revision=revision;d.sound.personalities=std::make_shared<RackPersonalityState>(*state);
        for(const bool group:{false,true}){d.group=group?grouped().group:std::optional<GroupIntent>{};juce::MemoryBlock wire;CHECK(encodeProjectState(d,wire));const auto valid=bytes(wire);
            CHECK(valid[4]==currentProjectStateVersion);ProjectDocument decoded;CHECK(decodeProjectState(valid.data(),valid.size(),decoded));CHECK(exact(decoded,d));
            juce::MemoryBlock sound;CHECK(encodeSoundState(d.sound,sound));CHECK(decodeProjectState(sound.getData(),sound.getSize(),decoded));CHECK(decoded.sound==d.sound);CHECK(!decoded.group);
            if(valid[4]!=15)continue;
            const auto reject=[&](Bytes bad){auto out=d;CHECK(!decodeProjectState(bad.data(),bad.size(),out));CHECK(exact(out,d));};
            auto b=valid;put(b,12,793945,4);sign(b);reject(b);b=valid;put(b,12,0xffffffff,4);sign(b);reject(b);
            b=valid;b.resize(b.size()-1);reject(b);b=valid;b.back()^=1;reject(b);
            b=valid;b[4]=2;sign(b);reject(b);b=valid;b[9]=2;sign(b);reject(b);
            b=valid;put(b,10,group?0:561,2);sign(b);reject(b);
            b=valid;put(b,24,3,4);signRange(b,20,sound.getSize());sign(b);reject(b);
            for(const auto size:{std::size_t(maximumProjectStateBytes),std::size_t(maximumProjectStateBytes+1)})reject(Bytes(size));
            auto owner=std::make_shared<CodecAliasState>();owner->instances=d.sound.personalities->instances;owner->wire=wire;auto alias=d;alias.sound.personalities=owner;
            std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();CHECK(decodeProjectState(input,wire.getSize(),alias));CHECK(exact(alias,d));CHECK(weak.expired());
            owner=std::make_shared<CodecAliasState>();owner->instances=d.sound.personalities->instances;owner->wire.replaceAll(b.data(),b.size());alias=d;alias.sound.personalities=owner;input=owner->wire.getData();weak=owner;owner.reset();
            CHECK(!decodeProjectState(input,b.size(),alias));CHECK(exact(alias,d));CHECK(!weak.expired());
            auto writable=std::make_shared<CodecAliasState>();writable->instances=d.sound.personalities->instances;alias=d;alias.sound.personalities=writable;CHECK(encodeProjectState(alias,writable->wire));CHECK(bytes(writable->wire)==valid);
        }
    }
