            for(std::size_t slot=0;slot<8;++slot){sound[8029+6*slot+2]=slot%2?2:1;want.sound.compatibility.effects[slot][2]=slot%2?2:1;}
            sound=oldSound7WithEmbeddedUnit(sound,instance);
