        for(std::size_t i=0;i<871;++i){CHECK(std::bit_cast<std::uint32_t>(out.sound.values[i])==read32(raw,20+8*i));CHECK(out.sound.controlLocks[i]==(raw[7126+i]!=0));}
        for(std::size_t slot=0;slot<8;++slot){for(std::size_t bank=0;bank<6;++bank)CHECK(out.sound.compatibility.effects[slot][bank]==sound[8029+6*slot+bank]);CHECK(out.sound.compatibility.effects[slot][6]==1);}
        juce::MemoryBlock upgraded;CHECK(encodeProjectState(out,upgraded));const auto current=bytes(upgraded);
        CHECK(current[4]==currentProjectStateVersion&&current[24]==currentSoundStateVersion&&read32(current,28)==4519);out={};CHECK(decodeProjectState(current.data(),current.size(),out));CHECK(exact(out,want));
        if(!embedded)CHECK(current.size()==41161);
