void old_project7_migration_and_domain_rejection()
{
    begin("old_project7_migration_and_domain_rejection");
    CHECK(oldSound8ParameterCount==911&&oldSound8NumericBytes==8369&&oldSound8CompatibilityBytes==72&&oldSound8StateSize==8481&&oldSound8MaximumBytes==795397);
    CHECK(oldProject7MinimumBytes==8589&&oldProject7MaximumBytes==800930);
    const auto capture=capturedOldProject7();const auto actualProject=bytes(capture);
    CHECK(actualProject[4]==7&&read32(actualProject,12)==8481);
    const Bytes raw(actualProject.begin()+20,actualProject.begin()+8501);
    CHECK(juce::SHA256(raw.data(),raw.size()).toHexString()=="863fdbf7b0df3d5479c642b97946f1a514edde985dc054ad098e2f85ff475584");
    ProjectDocument actual;CHECK(decodeProjectState(capture.getData(),capture.getSize(),actual));
    SoundDocument rawRecalled;CHECK(decodeSoundState(raw.data(),raw.size(),rawRecalled));CHECK(rawRecalled==actual.sound);
    const auto defaults=defaultParameterValues();
    for(std::size_t slot=0;slot<4;++slot)for(std::size_t bank=0;bank<2;++bank)CHECK(actual.sound.compatibility.synth[slot][bank]==raw[8381+2*slot+bank]);
    for(std::size_t i=0;i<911;++i){CHECK(std::bit_cast<std::uint32_t>(actual.sound.values[i])==read32(raw,20+8*i));CHECK(actual.sound.controlLocks[i]==(raw[7446+i]!=0));}
    for(std::size_t slot=0;slot<8;++slot){
        for(std::size_t bank=0;bank<7;++bank)CHECK(actual.sound.compatibility.effects[slot][bank]==raw[8389+7*slot+bank]);
        CHECK(actual.sound.compatibility.effects[slot][7]==1);
        for(std::size_t field=0;field<5;++field){const auto i=911+5*slot+field;CHECK(actual.sound.values[i]==defaults[i]&&!actual.sound.controlLocks[i]);}
    }
    RackInstance instance;instance.id=juce::Uuid("9138771513d34c57a47912251842d601");instance.design.id=juce::Uuid("9138771513d34c57a47912251842d602");
    instance.design.name="Retained Chorus42";instance.design.role=RackRole::fx;instance.design.revision=31;instance.design.panel.sections={"Tone"};
    RackUnit unit;unit.module=NativeModule::chorus;unit.algorithmRevision=1;const auto registry=parameterRegistry();
    for(std::size_t i=0;i<911;++i)if(registry[i].id.startsWith("effect.1."))unit.defaults.push_back({0,registry[i].id.substring(9),actual.sound.values[i]});
    CHECK(unit.defaults.size()==42);instance.design.units={unit};instance.bindings={{0,0}};instance.edited=true;
    instance.design.panel.controls={{"Rate",0,0,"chorus.rate_hz",FocusWidget::rotary,FocusResponse::linear,.1f,5}};
    CHECK(validateRackDesign(instance.design,RackValidationMode::instanceRecall));
    for(bool embedded:{false,true}){
        auto sound=raw;auto want=actual;Bytes valid=actualProject;
        if(embedded){
            // Supplementary explicitly re-signed rows/embedded data; the actual
            // native Project7 capture above remains byte-exact and independent.
            for(std::size_t slot=0;slot<8;++slot){sound[8389+7*slot+2]=slot%2?2:1;want.sound.compatibility.effects[slot][2]=slot%2?2:1;}
            sound=oldSound8WithEmbeddedUnit(sound,instance);
            CHECK(editRackLayout(want.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::chorus},want.sound.layout)==RackEditResult::applied);
            auto state=std::make_shared<RackPersonalityState>();state->instances={instance};want.sound.personalities=state;
            valid=envelope(sound,literalPatternFor(want.pattern),0);
        }
        CHECK(valid[4]==7&&valid[24]==8);ProjectDocument out=rich();CHECK(decodeProjectState(valid.data(),valid.size(),out));CHECK(exact(out,want));
        for(std::size_t i=0;i<911;++i){CHECK(std::bit_cast<std::uint32_t>(out.sound.values[i])==read32(raw,20+8*i));CHECK(out.sound.controlLocks[i]==(raw[7446+i]!=0));}
        for(std::size_t slot=0;slot<8;++slot){for(std::size_t bank=0;bank<7;++bank)CHECK(out.sound.compatibility.effects[slot][bank]==sound[8389+7*slot+bank]);CHECK(out.sound.compatibility.effects[slot][7]==1);}
        juce::MemoryBlock upgraded;CHECK(encodeProjectState(out,upgraded));const auto current=bytes(upgraded);
        CHECK(current[4]==currentProjectStateVersion&&current[24]==currentSoundStateVersion&&read32(current,28)==4519);out={};CHECK(decodeProjectState(current.data(),current.size(),out));CHECK(exact(out,want));
        if(!embedded)CHECK(current.size()==41161);
        out=want;CHECK(decodeProjectState(sound.data(),sound.size(),out));CHECK(out.sound==want.sound&&!out.group&&out.pattern==PatternDocument{});
        const auto reject=[&](const Bytes& bad){
            auto owner=std::make_shared<CodecAliasState>();if(want.sound.personalities)owner->instances=want.sound.personalities->instances;
            owner->wire.replaceAll(bad.data(),bad.size());out=want;out.sound.personalities=owner;const auto before=out;
            std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();
            CHECK(!decodeProjectState(input,bad.size(),out));CHECK(exact(out,before)&&out.sound.personalities==before.sound.personalities&&!weak.expired());CHECK(bytes(weak.lock()->wire)==bad);
        };
        for(const auto version:{6,8,9}){auto bad=valid;put(bad,4,version,2);sign(bad);reject(bad);}
        for(const auto length:{8480U,795398U,0xffffffffU}){auto bad=valid;put(bad,12,length,4);sign(bad);reject(bad);}
        auto bad=valid;bad.back()^=1;reject(bad);bad=valid;bad[20+sound.size()-1]^=1;sign(bad);reject(bad);
        for(int seam=0;seam<3;++seam){auto forged=sound;
            if(seam==0)put(forged,16,registry[911].stateKey,4);
            else if(seam==1){put(forged,7382,registry[911].stateKey,4);put(forged,7386,std::bit_cast<std::uint32_t>(.2f),4);}
            else forged[7335]=static_cast<std::uint8_t>(EffectKind::phaser);
            sign(forged);reject(envelope(forged,literalPatternFor(want.pattern),0));
        }
        if(embedded)for(int seam=0;seam<3;++seam){auto forged=instance;
            if(seam==0){forged.design.units[0].module=NativeModule::phaser;forged.design.units[0].defaults={{0,"phaser.rate_hz",.4f}};forged.design.panel.controls.clear();}
            else if(seam==1)forged.design.units[0].defaults.push_back({0,"phaser.rate_hz",.4f});
            else forged.design.panel.controls={{"Centre",0,0,"phaser.centre_hz",FocusWidget::rotary,FocusResponse::logarithmic,20,20000}};
            reject(envelope(oldSound8WithEmbeddedUnit(raw,forged),literalPatternFor(want.pattern),0));
        }
        auto owner=std::make_shared<CodecAliasState>();if(want.sound.personalities)owner->instances=want.sound.personalities->instances;owner->wire.replaceAll(valid.data(),valid.size());out=want;out.sound.personalities=owner;
        std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();CHECK(decodeProjectState(input,valid.size(),out));CHECK(exact(out,want)&&weak.expired());
    }
}
