void eq_project_and_sound_recall()
{
    begin("eq_project_and_sound_recall");
    auto base=rich();
    CHECK(editRackLayout(base.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::eq},base.sound.layout)==RackEditResult::applied);
    CHECK(editRackLayout(base.sound.layout,{RackEditKind::addEffect,1,masterChain,1,EffectKind::drive},base.sound.layout)==RackEditResult::applied);
    constexpr std::array<const char*,9> keys{"eq.low_shelf.frequency_hz","eq.low_shelf.gain_db","eq.low_shelf.q",
        "eq.bell.frequency_hz","eq.bell.gain_db","eq.bell.q","eq.high_shelf.frequency_hz","eq.high_shelf.gain_db","eq.high_shelf.q"};
    for(std::size_t slot=0;slot<8;++slot){
        base.sound.compatibility.effects[slot][2]=slot%2?2:1;
        for(std::size_t f=0;f<9;++f){
            const auto i=rackParameterIndex(NativeModule::eq,static_cast<std::uint8_t>(slot),keys[f]);CHECK(i&&*i==759+9*slot+f);
            if(i){base.sound.values[*i]=.1f+.06f*float(f)+.017f*float(slot);base.sound.controlLocks[*i]=(slot+f)%3==0;}
        }
    }
    for(std::size_t m=0;m<8;++m)base.sound.macros[m]={parameterRegistry()[759+9*m+m].stateKey,.2f-.04f*float(m)};
    base.sound.effectLocks[0]=true;base.sound.effectLocks[7]=true;
    RackInstance instance;instance.id=juce::Uuid("9138771513d34c57a47912251842e801");
    instance.design.id=juce::Uuid("9138771513d34c57a47912251842e802");instance.design.revision=21;
    instance.design.name="EQ recall";instance.design.role=RackRole::fx;instance.design.panel.sections={"Tone"};
    RackUnit unit;unit.module=NativeModule::eq;unit.algorithmRevision=1;
    for(std::size_t f=0;f<9;++f)unit.defaults.push_back({0,keys[f],.13f+.065f*float(f)});
    instance.design.units={unit};instance.design.panel.controls={{"Bell",0,0,"eq.bell.gain_db",FocusWidget::rotary,FocusResponse::linear,-18,18}};
    instance.bindings={{0,0}};instance.edited=true;CHECK(validateRackDesign(instance.design,RackValidationMode::portableDesign));
    for(bool embedded:{false,true})for(bool group:{false,true})for(int quality:{0,1}){
        auto source=base;source.sound.values[758]=float(quality);if(group)source.group=intent();
        if(embedded){auto state=std::make_shared<RackPersonalityState>();state->instances={instance};source.sound.personalities=state;}
        CHECK(validateProjectDocument(source));juce::MemoryBlock wire,sound;CHECK(encodeProjectState(source,wire));CHECK(encodeSoundState(source.sound,sound));
        const auto valid=bytes(wire);CHECK(valid.size()>=41161&&valid[4]==currentProjectStateVersion&&valid[24]==currentSoundStateVersion&&read32(valid,28)==4519);
        const auto oldSound=literalOldSound6(bytes(sound));
        const auto oldProject=group?groupedEnvelope(oldSound,literalPatternFor(source.pattern),1,*source.group):envelope(oldSound,literalPatternFor(source.pattern),1);
        ProjectDocument oldRecall;CHECK(oldProject[4]==5&&oldProject[24]==6);
        CHECK(decodeProjectState(oldProject.data(),oldProject.size(),oldRecall));CHECK(exact(oldRecall,source));
        auto wrongOldVersion=oldProject;put(wrongOldVersion,4,6,2);sign(wrongOldVersion);rejects(wrongOldVersion);
        ProjectDocument out;CHECK(decodeProjectState(wire.getData(),wire.getSize(),out));CHECK(exact(out,source));
        juce::MemoryBlock saved;CHECK(encodeProjectState(out,saved));CHECK(saved==wire);
        CHECK(decodeProjectState(sound.getData(),sound.getSize(),out));CHECK(out.sound==source.sound&&out.pattern==PatternDocument{}&&!out.group);
        for(std::size_t slot=0;slot<8;++slot){CHECK(out.sound.compatibility.effects[slot][4]==1);CHECK(out.sound.compatibility.effects[slot][2]==(slot%2?2:1));}
        for(std::size_t slot:{std::size_t(0),std::size_t(7)}){
            auto bad=valid;bad[20+currentSoundNumericBytes+20+effectBankCount*slot+4]=3;signRange(bad,20,sound.getSize());sign(bad);
            out=source;CHECK(!decodeProjectState(bad.data(),bad.size(),out));CHECK(exact(out,source));
            auto invalidSource=source;invalidSource.sound.compatibility.effects[slot][4]=3;invalid(invalidSource);
        }
        for(const auto field:{759U,830U}){
            auto bad=valid;put(bad,20+20+8*field,0x7fc00000,4);signRange(bad,20,sound.getSize());sign(bad);rejects(bad);
        }
        auto bad=valid;put(bad,4,4,2);sign(bad);out=source;CHECK(!decodeProjectState(bad.data(),bad.size(),out));CHECK(exact(out,source));
        bad=valid;put(bad,24,5,4);signRange(bad,20,sound.getSize());sign(bad);rejects(bad);
        bad=valid;put(bad,12,9216,4);sign(bad);rejects(bad);
        auto owner=std::make_shared<CodecAliasState>();if(source.sound.personalities)owner->instances=source.sound.personalities->instances;
        owner->wire=wire;out=source;out.sound.personalities=owner;std::weak_ptr<CodecAliasState> weak=owner;
        const auto* input=owner->wire.getData();owner.reset();CHECK(decodeProjectState(input,wire.getSize(),out));CHECK(exact(out,source)&&weak.expired());
    }
}
void modern_reverb_project_and_sound_recall()
{
    begin("modern_reverb_project_and_sound_recall");
    auto base=rich();
    CHECK(editRackLayout(base.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::reverb},base.sound.layout)==RackEditResult::applied);
    CHECK(editRackLayout(base.sound.layout,{RackEditKind::addEffect,1,masterChain,1,EffectKind::drive},base.sound.layout)==RackEditResult::applied);
    for(auto& banks:base.sound.compatibility.effects)banks[2]=2;
    base.sound.values[*rackParameterIndex(NativeModule::reverb,0,"reverb.mix")]=.37f;
    base.sound.values[*rackParameterIndex(NativeModule::reverb,7,"reverb.mix")]=.71f;
    RackInstance instance;instance.id=juce::Uuid("9138771513d34c57a47912251842d601");
    instance.design.id=juce::Uuid("9138771513d34c57a47912251842d602");instance.design.revision=17;
    instance.design.name="Modern recall";instance.design.role=RackRole::fx;instance.design.panel.sections={"Space"};
    instance.design.units={{0,NativeModule::reverb,{{0,"reverb.mix",.23f},{0,"reverb.decay_seconds",.41f}},2}};
    instance.design.panel.controls={{"Mix",0,0,"reverb.mix",FocusWidget::rotary,FocusResponse::linear,0,1}};
    instance.bindings={{0,0}};instance.edited=true;
    CHECK(validateRackDesign(instance.design,RackValidationMode::portableDesign));
    for(bool embedded:{false,true})for(bool group:{false,true})for(int quality:{0,1}){
        auto source=base;source.sound.values[758]=float(quality);source.group=group?grouped().group:std::optional<GroupIntent>{};
        if(embedded){auto state=std::make_shared<RackPersonalityState>();state->instances={instance};source.sound.personalities=state;}
        CHECK(validateProjectDocument(source));
        juce::MemoryBlock sound,project;CHECK(encodeSoundState(source.sound,sound));CHECK(encodeProjectState(source,project));
        const auto soundBytes=bytes(sound),projectBytes=bytes(project);
        CHECK(soundBytes.size()>=41053&&read32(soundBytes,4)==currentSoundStateVersion&&read32(soundBytes,8)==4519);
        CHECK(projectBytes.size()>=41161&&projectBytes[4]==currentProjectStateVersion&&projectBytes[5]==0);
        if(soundBytes.size()<41053||projectBytes.size()<41161)continue;
        // Current Sound30 has168 compatibility bytes after its40841 numeric bytes.
        CHECK(soundBytes[currentSoundNumericBytes]==168&&soundBytes[currentSoundNumericBytes+4]==1&&soundBytes[currentSoundNumericBytes+6]==4&&soundBytes[currentSoundNumericBytes+7]==2&&soundBytes[currentSoundNumericBytes+9]==19);
        for(std::size_t slot=0;slot<8;++slot)for(std::size_t bank=0;bank<effectBankCount;++bank)
            CHECK(soundBytes[currentSoundNumericBytes+20+effectBankCount*slot+bank]==(bank==2?2:1));
        const auto oldSound=literalOldSound5(soundBytes);
        const auto oldProject=group?groupedEnvelope(oldSound,literalPatternFor(source.pattern),1,*source.group):envelope(oldSound,literalPatternFor(source.pattern),1);
        CHECK(oldProject[4]==4&&oldProject[24]==5);ProjectDocument oldRecalled;
        CHECK(decodeProjectState(oldProject.data(),oldProject.size(),oldRecalled));CHECK(exact(oldRecalled,source));
        auto wrongVersion=oldProject;put(wrongVersion,4,5,2);sign(wrongVersion);rejects(wrongVersion);
        ProjectDocument decoded=rich();CHECK(decodeProjectState(project.getData(),project.getSize(),decoded));CHECK(exact(decoded,source));
        juce::MemoryBlock resaved;CHECK(encodeProjectState(decoded,resaved));CHECK(resaved==project);
        SoundDocument recalled;CHECK(decodeSoundState(sound.getData(),sound.getSize(),recalled));CHECK(recalled==source.sound);
        decoded=source;CHECK(decodeProjectState(sound.getData(),sound.getSize(),decoded));
        CHECK(decoded.sound==source.sound&&decoded.pattern==PatternDocument{}&&decoded.mode==PlaybackMode::externalMidi&&!decoded.group);
        if(embedded){CHECK(decoded.sound.personalities&&decoded.sound.personalities->instances.size()==1);
            if(decoded.sound.personalities&&decoded.sound.personalities->instances.size()==1)CHECK(decoded.sound.personalities->instances[0]==instance);}
        for(const auto mutation:std::array<std::pair<std::size_t,std::uint8_t>,4>{{{currentSoundNumericBytes+20+7*effectBankCount,3},{currentSoundNumericBytes+21+7*effectBankCount,3},{currentSoundNumericBytes+23+7*effectBankCount,3},{currentSoundNumericBytes+22+7*effectBankCount,3}}}){
            auto bad=projectBytes;bad[20+mutation.first]=mutation.second;signRange(bad,20,sound.getSize());sign(bad);
            auto out=source;CHECK(!decodeProjectState(bad.data(),bad.size(),out));CHECK(exact(out,source));
        }
        auto modernDrive=source;modernDrive.sound.compatibility.effects[1][0]=2;CHECK(validateProjectDocument(modernDrive));
        juce::MemoryBlock driveSound,driveProject;CHECK(encodeSoundState(modernDrive.sound,driveSound)&&encodeProjectState(modernDrive,driveProject));
        SoundDocument driveSoundRecalled;CHECK(decodeSoundState(driveSound.getData(),driveSound.getSize(),driveSoundRecalled)&&driveSoundRecalled==modernDrive.sound);
        ProjectDocument driveRecalled=rich();CHECK(decodeProjectState(driveProject.getData(),driveProject.getSize(),driveRecalled)&&exact(driveRecalled,modernDrive));
        auto invalidSource=source;invalidSource.sound.compatibility.effects[7][0]=3;invalid(invalidSource);
        invalidSource=source;invalidSource.sound.compatibility.synth[3][1]=3;invalid(invalidSource);
        if(embedded){
            invalidSource=source;invalidSource.sound.compatibility.effects[0][2]=1;invalid(invalidSource);
            auto mismatch=projectBytes;mismatch[20+currentSoundNumericBytes+22]=1;signRange(mismatch,20,sound.getSize());sign(mismatch);
            auto out=source;CHECK(!decodeProjectState(mismatch.data(),mismatch.size(),out));CHECK(exact(out,source));
        }
    }
}

void chorus_old_project6_evidence()
{
    begin("chorus_old_project6_evidence");
    const auto directory=juce::SystemStats::getEnvironmentVariable("AIRACK_CHORUS_OLD_PROJECT_EVIDENCE",{});
    if(directory.isEmpty())return;
    const juce::File folder(directory);CHECK(folder.createDirectory().wasOk());const auto registry=parameterRegistry();
    ProjectDocument old;
    for(std::size_t i=0;i<871;++i){if(registry[i].kind==ParameterKind::continuous)old.sound.values[i]=float((i*13)%71)/100;old.sound.controlLocks[i]=(i%17)==0;}
    for(auto& banks:old.sound.compatibility.effects)banks[2]=2;
    CHECK(validateProjectDocument(old));const auto file=folder.getChildFile("old-project6-nonuniform-inactive-filter-eq-reverb2.projectstate");
    if(!file.existsAsFile()){juce::MemoryBlock bytes;CHECK(parameterCount==871&&encodeProjectState(old,bytes));CHECK(file.replaceWithData(bytes.getData(),bytes.getSize()));}
    juce::MemoryBlock bytes;ProjectDocument recalled;CHECK(file.loadFileAsData(bytes));CHECK(decodeProjectState(bytes.getData(),bytes.getSize(),recalled));
    for(std::size_t i=0;i<871;++i)CHECK(recalled.sound.values[i]==old.sound.values[i]&&recalled.sound.controlLocks[i]==old.sound.controlLocks[i]);
    for(const auto& banks:recalled.sound.compatibility.effects)CHECK(banks[2]==2&&banks[4]==1&&banks[5]==1);
}

