Bytes oldSound10WithEmbeddedUnit(const Bytes& captured,const RackInstance& instance)
{
    // Supplementary re-signed insertion, retaining actual captured Sound10 fields.
    juce::MemoryBlock design;CHECK(encodeRackDesign(instance.design,design,RackValidationMode::instanceRecall));
    juce::MemoryOutputStream section;section.writeShort(1);section.writeByte(1);section.writeByte(0);
    section.write(instance.id.getRawData(),16);section.writeByte(instance.edited?1:0);section.writeByte(1);section.writeByte(0);section.writeByte(0);
    section.writeInt(static_cast<int>(design.getSize()));section.write(design.getData(),design.getSize());
    Bytes sound(captured.begin(),captured.begin()+9181);
    sound[7953]=1;sound[7954]=static_cast<std::uint8_t>(static_cast<unsigned>(instance.design.units[0].module)-2);
    sound[8009]=0;sound[8021]=1;
    const auto length=sound.size();sound.resize(length+4);put(sound,length,section.getDataSize(),4);
    const auto* data=static_cast<const std::uint8_t*>(section.getData());sound.insert(sound.end(),data,data+section.getDataSize());
    sound.resize(sound.size()+32);sign(sound);return sound;
}

void old_project9_migration_and_domain_rejection()
{
    begin("old_project9_migration_and_domain_rejection");
    CHECK(oldSound10ParameterCount==991&&oldSound10NumericBytes==9089&&oldSound10CompatibilityBytes==88&&oldSound10StateSize==9217&&oldSound10MaximumBytes==796133);
    CHECK(oldProject9MinimumBytes==9325&&oldProject9MaximumBytes==801666);
    const auto capture=capturedOldProject9();const auto actualProject=bytes(capture);
    CHECK(actualProject[4]==9&&read32(actualProject,12)==9217);
    const Bytes raw(actualProject.begin()+20,actualProject.begin()+9237);
    CHECK(juce::SHA256(raw.data(),raw.size()).toHexString()=="785c4bb7d42bdaf55b16b6ccb3dd77c7fcbb2d03c67ab8090f7a719db52f757b");
    ProjectDocument actual;CHECK(decodeProjectState(capture.getData(),capture.getSize(),actual));
    SoundDocument rawRecalled;CHECK(decodeSoundState(raw.data(),raw.size(),rawRecalled));CHECK(rawRecalled==actual.sound);
    const auto defaults=defaultParameterValues();
    for(std::size_t slot=0;slot<4;++slot)for(std::size_t bank=0;bank<2;++bank)CHECK(actual.sound.compatibility.synth[slot][bank]==raw[9101+2*slot+bank]);
    for(std::size_t i=0;i<991;++i){CHECK(std::bit_cast<std::uint32_t>(actual.sound.values[i])==read32(raw,20+8*i));CHECK(actual.sound.controlLocks[i]==(raw[8086+i]!=0));}
    for(std::size_t slot=0;slot<8;++slot){
        for(std::size_t bank=0;bank<9;++bank)CHECK(actual.sound.compatibility.effects[slot][bank]==raw[9109+9*slot+bank]);
        CHECK(actual.sound.compatibility.effects[slot][9]==1);
        for(std::size_t field=0;field<4;++field){const auto i=991+4*slot+field;CHECK(actual.sound.values[i]==defaults[i]&&!actual.sound.controlLocks[i]);}
    }
    RackInstance instance;instance.id=juce::Uuid("9138771513d34c57a47912251842d601");instance.design.id=juce::Uuid("9138771513d34c57a47912251842d602");
    instance.design.name="Retained Flanger47";instance.design.role=RackRole::fx;instance.design.revision=31;instance.design.panel.sections={"Tone"};
    RackUnit unit;unit.module=NativeModule::flanger;unit.algorithmRevision=1;const auto registry=parameterRegistry();
    for(std::size_t i=0;i<991;++i)if(registry[i].id.startsWith("effect.1."))unit.defaults.push_back({0,registry[i].id.substring(9),actual.sound.values[i]});
    CHECK(unit.defaults.size()==52);instance.design.units={unit};instance.bindings={{0,0}};instance.edited=true;
    instance.design.panel.controls={{"Rate",0,0,"flanger.rate_hz",FocusWidget::rotary,FocusResponse::linear,.1f,5}};
    CHECK(validateRackDesign(instance.design,RackValidationMode::instanceRecall));
    for(bool embedded:{false,true}){
        auto sound=raw;auto want=actual;Bytes valid=actualProject;
        if(embedded){
            // Supplementary explicitly re-signed rows/embedded data; the actual
            // native Project9 capture above remains byte-exact and independent.
            for(std::size_t slot=0;slot<8;++slot){sound[9109+9*slot+2]=slot%2?2:1;want.sound.compatibility.effects[slot][2]=slot%2?2:1;}
            sound=oldSound10WithEmbeddedUnit(sound,instance);
            CHECK(editRackLayout(want.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::flanger},want.sound.layout)==RackEditResult::applied);
            auto state=std::make_shared<RackPersonalityState>();state->instances={instance};want.sound.personalities=state;
            valid=envelope(sound,literalPatternFor(want.pattern),0);
        }
        CHECK(valid[4]==9&&valid[24]==10);ProjectDocument out=rich();CHECK(decodeProjectState(valid.data(),valid.size(),out));CHECK(exact(out,want));
        for(std::size_t i=0;i<991;++i){CHECK(std::bit_cast<std::uint32_t>(out.sound.values[i])==read32(raw,20+8*i));CHECK(out.sound.controlLocks[i]==(raw[8086+i]!=0));}
        for(std::size_t slot=0;slot<8;++slot){for(std::size_t bank=0;bank<9;++bank)CHECK(out.sound.compatibility.effects[slot][bank]==sound[9109+9*slot+bank]);CHECK(out.sound.compatibility.effects[slot][9]==1);}
        juce::MemoryBlock upgraded;CHECK(encodeProjectState(out,upgraded));const auto current=bytes(upgraded);
        CHECK(current[4]==currentProjectStateVersion&&current[24]==currentSoundStateVersion&&read32(current,28)==4519);out={};CHECK(decodeProjectState(current.data(),current.size(),out));CHECK(exact(out,want));
        if(!embedded)CHECK(current.size()==41161);
        out=want;CHECK(decodeProjectState(sound.data(),sound.size(),out));CHECK(out.sound==want.sound&&!out.group&&out.pattern==PatternDocument{});
        const auto reject=[&](const Bytes& bad){
            auto owner=std::make_shared<CodecAliasState>();if(want.sound.personalities)owner->instances=want.sound.personalities->instances;
            owner->wire.replaceAll(bad.data(),bad.size());out=want;out.sound.personalities=owner;const auto before=out;
            std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();
            CHECK(!decodeProjectState(input,bad.size(),out));CHECK(exact(out,before)&&out.sound.personalities==before.sound.personalities&&!weak.expired());CHECK(bytes(weak.lock()->wire)==bad);
        };
        for(const auto version:{8,10,12}){auto bad=valid;put(bad,4,version,2);sign(bad);reject(bad);}
        for(const auto length:{9216U,796134U,0xffffffffU}){auto bad=valid;put(bad,12,length,4);sign(bad);reject(bad);}
        auto bad=valid;bad.back()^=1;reject(bad);bad=valid;bad[20+sound.size()-1]^=1;sign(bad);reject(bad);
        for(int seam=0;seam<3;++seam){auto forged=sound;
            if(seam==0)put(forged,16,registry[991].stateKey,4);
            else if(seam==1){put(forged,8022,registry[991].stateKey,4);put(forged,8026,std::bit_cast<std::uint32_t>(.2f),4);}
            else forged[7975]=static_cast<std::uint8_t>(EffectKind::stereo);
            sign(forged);reject(envelope(forged,literalPatternFor(want.pattern),0));
        }
        if(embedded)for(int seam=0;seam<3;++seam){auto forged=instance;
            if(seam==0){forged.design.units[0].module=NativeModule::stereo;forged.design.units[0].defaults={{0,"stereo.gain_db",.4f}};forged.design.panel.controls.clear();}
            else if(seam==1)forged.design.units[0].defaults.push_back({0,"stereo.gain_db",.4f});
            else forged.design.panel.controls={{"Delay",0,0,"stereo.width",FocusWidget::rotary,FocusResponse::linear,0,2}};
            reject(envelope(oldSound10WithEmbeddedUnit(raw,forged),literalPatternFor(want.pattern),0));
        }
        auto owner=std::make_shared<CodecAliasState>();if(want.sound.personalities)owner->instances=want.sound.personalities->instances;owner->wire.replaceAll(valid.data(),valid.size());out=want;out.sound.personalities=owner;
        std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();CHECK(decodeProjectState(input,valid.size(),out));CHECK(exact(out,want)&&weak.expired());
    }
}
void stereo_project_recall_and_atomic_rejection()
{
    begin("stereo_project_recall_and_atomic_rejection");
    auto source=rich();source.group=intent();
    CHECK(editRackLayout(source.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::stereo},source.sound.layout)==RackEditResult::applied);
    CHECK(editRackLayout(source.sound.layout,{RackEditKind::addEffect,1,masterChain,1,EffectKind::flanger},source.sound.layout)==RackEditResult::applied);
    constexpr std::array<const char*,4> keys{"stereo.gain_db","stereo.pan","stereo.width","stereo.channel_mode"};
    for(std::size_t slot=0;slot<8;++slot){
        source.sound.compatibility.effects[slot][2]=slot%2?2:1;
        for(std::size_t field=0;field<4;++field){const auto index=rackParameterIndex(NativeModule::stereo,static_cast<std::uint8_t>(slot),keys[field]);CHECK(index&&*index==991+4*slot+field);
            if(index){source.sound.values[*index]=field==3?float(slot%3)/2:.12f+.14f*float(field)+.02f*float(slot);source.sound.controlLocks[*index]=(slot+field)%2==0;}}
        source.sound.macros[slot]={parameterRegistry()[991+4*slot+slot%3].stateKey,.2f-.0375f*float(slot)};
        source.sound.values[1+slot]=.1f+.04f*float(slot);
    }
    source.sound.effectLocks[0]=true;source.sound.effectLocks[7]=true;
    RackInstance instance;instance.id=juce::Uuid("9138771513d34c57a47912251842f701");instance.design.id=juce::Uuid("9138771513d34c57a47912251842f702");
    instance.design.name="Stereo recall";instance.design.role=RackRole::fx;instance.design.panel.sections={"Motion"};instance.design.revision=19;
    RackUnit unit;unit.module=NativeModule::stereo;unit.algorithmRevision=1;
    for(std::size_t field=0;field<4;++field)unit.defaults.push_back({0,keys[field],field==3?.5f:.17f+.11f*float(field)});
    unit.defaults.push_back({0,"flanger.mix",.37f});instance.design.units={unit};instance.bindings={{0,0}};instance.edited=true;
    instance.design.panel.controls={{"Delay",0,0,"stereo.width",FocusWidget::rotary,FocusResponse::linear,0,2}};
    CHECK(validateRackDesign(instance.design,RackValidationMode::instanceRecall));
    for(bool embedded:{false,true}){
        auto original=source;if(embedded){auto state=std::make_shared<RackPersonalityState>();state->instances={instance};original.sound.personalities=state;}
        CHECK(validateProjectDocument(original));juce::MemoryBlock project,sound;CHECK(encodeProjectState(original,project));CHECK(encodeSoundState(original.sound,sound));
        const auto valid=bytes(project);CHECK(valid.size()>=41161&&valid[4]==currentProjectStateVersion&&valid[24]==currentSoundStateVersion&&read32(valid,28)==4519);
        ProjectDocument out;CHECK(decodeProjectState(project.getData(),project.getSize(),out));CHECK(exact(out,original));juce::MemoryBlock saved;CHECK(encodeProjectState(out,saved));CHECK(saved==project);
        CHECK(decodeProjectState(sound.getData(),sound.getSize(),out));CHECK(out.sound==original.sound&&out.pattern==PatternDocument{}&&!out.group);
        const auto reject=[&](const Bytes& bad){
            auto owner=std::make_shared<CodecAliasState>();if(original.sound.personalities)owner->instances=original.sound.personalities->instances;
            owner->wire.replaceAll(bad.data(),bad.size());out=original;out.sound.personalities=owner;const auto before=out;
            std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();
            CHECK(!decodeProjectState(input,bad.size(),out));CHECK(exact(out,before)&&out.sound.personalities==before.sound.personalities&&!weak.expired());CHECK(bytes(weak.lock()->wire)==bad);
        };
        for(std::size_t slot:{std::size_t(0),std::size_t(7)}){
            auto bad=valid;bad[20+currentSoundNumericBytes+20+effectBankCount*slot+9]=2;signRange(bad,20,sound.getSize());sign(bad);reject(bad);
            auto invalidSource=original;invalidSource.sound.compatibility.effects[slot][9]=2;invalid(invalidSource);
        }
        for(const auto field:{991U,1022U}){auto bad=valid;put(bad,20+20+8*field,0x7fc00000U,4);signRange(bad,20,sound.getSize());sign(bad);reject(bad);}
        for(const auto version:{9,255}){auto bad=valid;put(bad,4,version,2);sign(bad);reject(bad);}
        auto bad=valid;put(bad,24,9,4);signRange(bad,20,sound.getSize());sign(bad);reject(bad);
        for(const auto length:{9512U,796430U,0xffffffffU}){bad=valid;put(bad,12,length,4);sign(bad);reject(bad);}
        bad=valid;bad.back()^=1;reject(bad);bad=valid;bad[20+sound.getSize()-1]^=1;sign(bad);reject(bad);
        if(embedded){bad=valid;bad[20+16+8*parameterCount+10]=static_cast<std::uint8_t>(EffectKind::flanger);signRange(bad,20,sound.getSize());sign(bad);reject(bad);
            auto invalidSource=original;auto state=std::make_shared<RackPersonalityState>(*original.sound.personalities);state->instances[0].design.units[0].algorithmRevision=2;invalidSource.sound.personalities=state;invalid(invalidSource);}
        auto owner=std::make_shared<CodecAliasState>();if(original.sound.personalities)owner->instances=original.sound.personalities->instances;owner->wire=project;out=original;out.sound.personalities=owner;
        std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();CHECK(decodeProjectState(input,project.getSize(),out));CHECK(exact(out,original)&&weak.expired());
    }
}


