Bytes oldSound11WithEmbeddedUnit(const Bytes& captured,const RackInstance& instance)
{
    // Supplementary re-signed insertion, retaining actual captured Sound11 fields.
    juce::MemoryBlock design;CHECK(encodeRackDesign(instance.design,design,RackValidationMode::instanceRecall));
    juce::MemoryOutputStream section;section.writeShort(1);section.writeByte(1);section.writeByte(0);
    section.write(instance.id.getRawData(),16);section.writeByte(instance.edited?1:0);section.writeByte(1);section.writeByte(0);section.writeByte(0);
    section.writeInt(static_cast<int>(design.getSize()));section.write(design.getData(),design.getSize());
    Bytes sound(captured.begin(),captured.begin()+9477);
    sound[8209]=1;sound[8210]=static_cast<std::uint8_t>(static_cast<unsigned>(instance.design.units[0].module)-2);
    sound[8265]=0;sound[8277]=1;
    const auto length=sound.size();sound.resize(length+4);put(sound,length,section.getDataSize(),4);
    const auto* data=static_cast<const std::uint8_t*>(section.getData());sound.insert(sound.end(),data,data+section.getDataSize());
    sound.resize(sound.size()+32);sign(sound);return sound;
}

void old_project10_migration_and_domain_rejection()
{
    begin("old_project10_migration_and_domain_rejection");
    CHECK(oldSound11ParameterCount==1023&&oldSound11NumericBytes==9377&&oldSound11CompatibilityBytes==96&&oldSound11StateSize==9513&&oldSound11MaximumBytes==796429);
    CHECK(oldProject10MinimumBytes==9621&&oldProject10MaximumBytes==801962);
    const auto capture=capturedDimensionOldProject10();const auto actualProject=bytes(capture);
    CHECK(actualProject[4]==10&&read32(actualProject,12)==9513);
    const Bytes raw(actualProject.begin()+20,actualProject.begin()+9533);
    CHECK(juce::SHA256(raw.data(),raw.size()).toHexString()=="07e03ad18e85b60778eca8e954387a7110fcd6340097029cdeec719bd3da5a6c");
    ProjectDocument actual;CHECK(decodeProjectState(capture.getData(),capture.getSize(),actual));
    SoundDocument rawRecalled;CHECK(decodeSoundState(raw.data(),raw.size(),rawRecalled));CHECK(rawRecalled==actual.sound);
    const auto defaults=defaultParameterValues();
    for(std::size_t slot=0;slot<4;++slot)for(std::size_t bank=0;bank<2;++bank)CHECK(actual.sound.compatibility.synth[slot][bank]==raw[9389+2*slot+bank]);
    for(std::size_t i=0;i<1023;++i){CHECK(std::bit_cast<std::uint32_t>(actual.sound.values[i])==read32(raw,20+8*i));CHECK(actual.sound.controlLocks[i]==(raw[8342+i]!=0));}
    for(std::size_t slot=0;slot<8;++slot){
        for(std::size_t bank=0;bank<10;++bank)CHECK(actual.sound.compatibility.effects[slot][bank]==raw[9397+10*slot+bank]);
        CHECK(actual.sound.compatibility.effects[slot][10]==1);
        for(std::size_t field=0;field<4;++field){const auto i=1023+4*slot+field;CHECK(actual.sound.values[i]==defaults[i]&&!actual.sound.controlLocks[i]);}
    }
    RackInstance instance;instance.id=juce::Uuid("9138771513d34c57a47912251842d601");instance.design.id=juce::Uuid("9138771513d34c57a47912251842d602");
    instance.design.name="Retained Stereo56";instance.design.role=RackRole::fx;instance.design.revision=31;instance.design.panel.sections={"Tone"};
    RackUnit unit;unit.module=NativeModule::stereo;unit.algorithmRevision=1;const auto registry=parameterRegistry();
    for(std::size_t i=0;i<1023;++i)if(registry[i].id.startsWith("effect.1."))unit.defaults.push_back({0,registry[i].id.substring(9),actual.sound.values[i]});
    CHECK(unit.defaults.size()==56);instance.design.units={unit};instance.bindings={{0,0}};instance.edited=true;
    instance.design.panel.controls={{"Rate",0,0,"stereo.width",FocusWidget::rotary,FocusResponse::linear,0,2}};
    CHECK(validateRackDesign(instance.design,RackValidationMode::instanceRecall));
    for(bool embedded:{false,true}){
        auto sound=raw;auto want=actual;Bytes valid=actualProject;
        if(embedded){
            // Supplementary explicitly re-signed rows/embedded data; the actual
            // native Project10 capture above remains byte-exact and independent.
            for(std::size_t slot=0;slot<8;++slot){sound[9397+10*slot+2]=slot%2?2:1;want.sound.compatibility.effects[slot][2]=slot%2?2:1;}
            sound=oldSound11WithEmbeddedUnit(sound,instance);
            CHECK(editRackLayout(want.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::stereo},want.sound.layout)==RackEditResult::applied);
            auto state=std::make_shared<RackPersonalityState>();state->instances={instance};want.sound.personalities=state;
            valid=envelope(sound,literalPatternFor(want.pattern),0);
        }
        CHECK(valid[4]==10&&valid[24]==11);ProjectDocument out=rich();CHECK(decodeProjectState(valid.data(),valid.size(),out));CHECK(exact(out,want));
        for(std::size_t i=0;i<1023;++i){CHECK(std::bit_cast<std::uint32_t>(out.sound.values[i])==read32(raw,20+8*i));CHECK(out.sound.controlLocks[i]==(raw[8342+i]!=0));}
        for(std::size_t slot=0;slot<8;++slot){for(std::size_t bank=0;bank<10;++bank)CHECK(out.sound.compatibility.effects[slot][bank]==sound[9397+10*slot+bank]);CHECK(out.sound.compatibility.effects[slot][10]==1);}
        juce::MemoryBlock upgraded;CHECK(encodeProjectState(out,upgraded));const auto current=bytes(upgraded);
        CHECK(current[4]==currentProjectStateVersion&&current[24]==currentSoundStateVersion&&read32(current,28)==4519);out={};CHECK(decodeProjectState(current.data(),current.size(),out));CHECK(exact(out,want));
        if(!embedded)CHECK(current.size()==41161);
        out=want;CHECK(decodeProjectState(sound.data(),sound.size(),out));CHECK(out.sound==want.sound&&!out.group&&out.pattern==PatternDocument{});
        const auto reject=[&](const Bytes& bad){
            auto owner=std::make_shared<CodecAliasState>();if(want.sound.personalities)owner->instances=want.sound.personalities->instances;
            owner->wire.replaceAll(bad.data(),bad.size());out=want;out.sound.personalities=owner;const auto before=out;
            std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();
            CHECK(!decodeProjectState(input,bad.size(),out));CHECK(exact(out,before)&&out.sound.personalities==before.sound.personalities&&!weak.expired());CHECK(bytes(weak.lock()->wire)==bad);
        };
        for(const auto version:{8,11,12}){auto bad=valid;put(bad,4,version,2);sign(bad);reject(bad);}
        for(const auto length:{9512U,796430U,0xffffffffU}){auto bad=valid;put(bad,12,length,4);sign(bad);reject(bad);}
        auto bad=valid;bad.back()^=1;reject(bad);bad=valid;bad[20+sound.size()-1]^=1;sign(bad);reject(bad);
        for(int seam=0;seam<3;++seam){auto forged=sound;
            if(seam==0)put(forged,16,registry[1023].stateKey,4);
            else if(seam==1){put(forged,8278,registry[1023].stateKey,4);put(forged,8282,std::bit_cast<std::uint32_t>(.2f),4);}
            else forged[8210]=static_cast<std::uint8_t>(EffectKind::dimension);
            sign(forged);reject(envelope(forged,literalPatternFor(want.pattern),0));
        }
        if(embedded)for(int seam=0;seam<3;++seam){auto forged=instance;
            if(seam==0){forged.design.units[0].module=NativeModule::dimension;forged.design.units[0].defaults={{0,"dimension.depth",.4f}};forged.design.panel.controls.clear();}
            else if(seam==1)forged.design.units[0].defaults.push_back({0,"dimension.depth",.4f});
            else forged.design.panel.controls={{"Delay",0,0,"dimension.width",FocusWidget::rotary,FocusResponse::linear,0,2}};
            reject(envelope(oldSound11WithEmbeddedUnit(raw,forged),literalPatternFor(want.pattern),0));
        }
        auto owner=std::make_shared<CodecAliasState>();if(want.sound.personalities)owner->instances=want.sound.personalities->instances;owner->wire.replaceAll(valid.data(),valid.size());out=want;out.sound.personalities=owner;
        std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();CHECK(decodeProjectState(input,valid.size(),out));CHECK(exact(out,want)&&weak.expired());
    }
}

void dimension_project_recall_and_atomic_rejection()
{
    begin("dimension_project_recall_and_atomic_rejection");
    auto source=rich();source.group=intent();
    CHECK(editRackLayout(source.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::dimension},source.sound.layout)==RackEditResult::applied);
    CHECK(editRackLayout(source.sound.layout,{RackEditKind::addEffect,1,masterChain,1,EffectKind::flanger},source.sound.layout)==RackEditResult::applied);
    constexpr std::array<const char*,4> keys{"dimension.depth","dimension.rate_hz","dimension.width","dimension.mix"};
    for(std::size_t slot=0;slot<8;++slot){
        source.sound.compatibility.effects[slot][2]=slot%2?2:1;
        for(std::size_t field=0;field<4;++field){const auto index=rackParameterIndex(NativeModule::dimension,static_cast<std::uint8_t>(slot),keys[field]);CHECK(index&&*index==1023+4*slot+field);
            if(index){source.sound.values[*index]=.12f+.14f*float(field)+.02f*float(slot);source.sound.controlLocks[*index]=(slot+field)%2==0;}}
        source.sound.macros[slot]={parameterRegistry()[1023+4*slot+slot%3].stateKey,.2f-.0375f*float(slot)};
        source.sound.values[1+slot]=.1f+.04f*float(slot);
    }
    source.sound.effectLocks[0]=true;source.sound.effectLocks[7]=true;
    RackInstance instance;instance.id=juce::Uuid("9138771513d34c57a47912251842f701");instance.design.id=juce::Uuid("9138771513d34c57a47912251842f702");
    instance.design.name="Stereo recall";instance.design.role=RackRole::fx;instance.design.panel.sections={"Motion"};instance.design.revision=19;
    RackUnit unit;unit.module=NativeModule::dimension;unit.algorithmRevision=1;
    for(std::size_t field=0;field<4;++field)unit.defaults.push_back({0,keys[field],.17f+.11f*float(field)});
    unit.defaults.push_back({0,"flanger.mix",.37f});instance.design.units={unit};instance.bindings={{0,0}};instance.edited=true;
    instance.design.panel.controls={{"Delay",0,0,"dimension.width",FocusWidget::rotary,FocusResponse::linear,0,2}};
    CHECK(validateRackDesign(instance.design,RackValidationMode::instanceRecall));
    for(bool embedded:{false,true}){
        auto original=source;if(embedded){auto state=std::make_shared<RackPersonalityState>();state->instances={instance};original.sound.personalities=state;}
        CHECK(validateProjectDocument(original));juce::MemoryBlock project,sound;CHECK(encodeProjectState(original,project));CHECK(encodeSoundState(original.sound,sound));
        const auto valid=bytes(project);CHECK(valid.size()>=41161&&valid[4]==currentProjectStateVersion&&valid[24]==currentSoundStateVersion&&read32(valid,28)==4519);
        ProjectDocument out;CHECK(decodeProjectState(project.getData(),project.getSize(),out));CHECK(exact(out,original));juce::MemoryBlock saved;CHECK(encodeProjectState(out,saved));CHECK(saved==project);
        CHECK(decodeProjectState(sound.getData(),sound.getSize(),out));CHECK(out.sound==original.sound&&out.pattern==PatternDocument{}&&!out.group);
        const auto reject=[&](const Bytes& bad){
            auto owner=std::make_shared<CodecAliasState>();if(original.sound.personalities)owner->instances=original.sound.personalities->instances;
            owner->wire.replaceAll(bad.data(),bad.size());out=original;out.sound.personalities=owner;const auto before=out;
            std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();
            CHECK(!decodeProjectState(input,bad.size(),out));CHECK(exact(out,before)&&out.sound.personalities==before.sound.personalities&&!weak.expired());CHECK(bytes(weak.lock()->wire)==bad);
        };
        for(std::size_t slot:{std::size_t(0),std::size_t(7)}){
            auto bad=valid;bad[20+currentSoundNumericBytes+20+effectBankCount*slot+10]=3;signRange(bad,20,sound.getSize());sign(bad);reject(bad);
            auto invalidSource=original;invalidSource.sound.compatibility.effects[slot][10]=3;invalid(invalidSource);
        }
        for(const auto field:{1023U,1054U}){auto bad=valid;put(bad,20+20+8*field,0x7fc00000U,4);signRange(bad,20,sound.getSize());sign(bad);reject(bad);}
        for(const auto version:{10,255}){auto bad=valid;put(bad,4,version,2);sign(bad);reject(bad);}
        auto bad=valid;put(bad,24,10,4);signRange(bad,20,sound.getSize());sign(bad);reject(bad);
        for(const auto length:{9808U,796726U,0xffffffffU}){bad=valid;put(bad,12,length,4);sign(bad);reject(bad);}
        bad=valid;bad.back()^=1;reject(bad);bad=valid;bad[20+sound.getSize()-1]^=1;sign(bad);reject(bad);
        if(embedded){bad=valid;bad[20+8456+10]=static_cast<std::uint8_t>(EffectKind::flanger);signRange(bad,20,sound.getSize());sign(bad);reject(bad);
            auto invalidSource=original;auto state=std::make_shared<RackPersonalityState>(*original.sound.personalities);state->instances[0].design.units[0].algorithmRevision=2;invalidSource.sound.personalities=state;invalid(invalidSource);}
        auto owner=std::make_shared<CodecAliasState>();if(original.sound.personalities)owner->instances=original.sound.personalities->instances;owner->wire=project;out=original;out.sound.personalities=owner;
        std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();CHECK(decodeProjectState(input,project.getSize(),out));CHECK(exact(out,original)&&weak.expired());
    }
}

void dimension_old_project10_evidence()
{
    begin("dimension_old_project10_evidence");
    const auto directory=juce::SystemStats::getEnvironmentVariable("AIRACK_DIMENSION_OLD_PROJECT_EVIDENCE",{});
    if(directory.isEmpty())return;
    const juce::File folder(directory);CHECK(folder.createDirectory().wasOk());const auto registry=parameterRegistry();
    ProjectDocument old;for(std::size_t i=0;i<1023;++i){if(registry[i].kind==ParameterKind::continuous)old.sound.values[i]=float((i*13)%71)/100;old.sound.controlLocks[i]=(i%17)==0;}
    for(auto& banks:old.sound.compatibility.effects)banks[2]=2;
    CHECK(validateProjectDocument(old));const auto file=folder.getChildFile("old-project10-nonuniform-inactive-stereo-flanger-phaser-chorus-filter-eq-reverb2.projectstate");
    if(!file.existsAsFile()){juce::MemoryBlock bytes;CHECK(parameterCount==1023&&encodeProjectState(old,bytes));CHECK(file.replaceWithData(bytes.getData(),bytes.getSize()));}
    juce::MemoryBlock bytes;ProjectDocument recalled;CHECK(file.loadFileAsData(bytes));CHECK(decodeProjectState(bytes.getData(),bytes.getSize(),recalled));
    for(std::size_t i=0;i<1023;++i)CHECK(recalled.sound.values[i]==old.sound.values[i]&&recalled.sound.controlLocks[i]==old.sound.controlLocks[i]);
    for(const auto& banks:recalled.sound.compatibility.effects)CHECK(banks[2]==2&&banks[4]==1&&banks[5]==1&&banks[6]==1&&banks[7]==1&&banks[8]==1&&banks[9]==1);
}
