void frequency_shift_project_migration_recall_and_atomic_rejection()
{
    begin("frequency_shift_project_migration_recall_and_atomic_rejection");CHECK(oldProject11MinimumBytes==9917&&oldProject11MaximumBytes==802258);
    const auto captured=capturedFrequencyShiftOldProject11();ProjectDocument migrated;const bool decoded=decodeProjectState(captured.getData(),captured.getSize(),migrated);CHECK(decoded);if(!decoded)return;
    const auto native=bytes(captured);CHECK(native[4]==11&&native[24]==12&&read32(native,28)==1055);const auto defaults=defaultParameterValues();
    for(std::size_t i=0;i<1055;++i){CHECK(std::bit_cast<std::uint32_t>(migrated.sound.values[i])==read32(native,40+8*i));CHECK(migrated.sound.controlLocks[i]==(native[8618+i]!=0));}
    for(std::size_t slot=0;slot<8;++slot){for(std::size_t bank=0;bank<11;++bank)CHECK(migrated.sound.compatibility.effects[slot][bank]==native[9705+11*slot+bank]);CHECK(migrated.sound.compatibility.effects[slot][11]==1);}
    for(std::size_t i=1055;i<parameterCount;++i)CHECK(migrated.sound.values[i]==defaults[i]&&!migrated.sound.controlLocks[i]);
    juce::MemoryBlock upgraded;CHECK(encodeProjectState(migrated,upgraded));CHECK(bytes(upgraded)[4]==currentProjectStateVersion&&bytes(upgraded)[24]==currentSoundStateVersion&&upgraded.getSize()==41161);ProjectDocument out;CHECK(decodeProjectState(upgraded.getData(),upgraded.getSize(),out)&&exact(out,migrated));
    const auto rejectOld=[&](Bytes bad){sign(bad);auto held=migrated;CHECK(!decodeProjectState(bad.data(),bad.size(),held)&&exact(held,migrated));};
    for(unsigned version:{10,12,13}){auto bad=native;put(bad,4,version,2);rejectOld(bad);}for(int seam=0;seam<3;++seam){auto bad=native;if(seam==0)put(bad,36,parameterRegistry()[1055].stateKey,4);else if(seam==1)put(bad,24,13,4);else bad[20+8466]=11;signRange(bad,20,9809);rejectOld(bad);}
    auto source=rich();source.group=intent();CHECK(editRackLayout(source.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::frequencyShift},source.sound.layout)==RackEditResult::applied);
    constexpr std::array<const char*,3> keys{"frequency_shift.hz","frequency_shift.stereo_offset_hz","frequency_shift.mix"};
    for(std::size_t slot=0;slot<8;++slot){source.sound.compatibility.effects[slot][2]=1+slot%2;for(std::size_t field=0;field<3;++field){source.sound.values[1055+3*slot+field]=.17f+.09f*float((slot+field)%8);source.sound.controlLocks[1055+3*slot+field]=(slot+field)%2==0;}source.sound.macros[slot]={parameterRegistry()[1055+3*slot+slot%3].stateKey,.2f-.0375f*float(slot)};source.sound.values[1+slot]=.1f+.04f*float(slot);}
    RackInstance instance;instance.design.name="Shifter retained63";instance.design.role=RackRole::fx;instance.design.panel.sections={"Translation"};instance.design.units={{0,NativeModule::frequencyShift,{}}};instance.bindings={{0,0}};
    for(std::size_t i=0;i<dynamicEqParameterStart;++i)if(parameterRegistry()[i].id.startsWith("effect.1."))instance.design.units[0].defaults.push_back({0,parameterRegistry()[i].id.substring(9),source.sound.values[i]});CHECK(instance.design.units[0].defaults.size()==82);instance.design.panel.controls={{"Shift",0,0,keys[0],FocusWidget::rotary,FocusResponse::linear,-1000,1000}};
    for(bool embedded:{false,true}){auto want=source;if(embedded){auto state=std::make_shared<RackPersonalityState>();state->instances={instance};want.sound.personalities=state;}juce::MemoryBlock wire;CHECK(encodeProjectState(want,wire));if(wire.getSize()<20)continue;const auto valid=bytes(wire);CHECK(valid[4]==currentProjectStateVersion&&valid[24]==currentSoundStateVersion&&read32(valid,28)==4519);CHECK(decodeProjectState(valid.data(),valid.size(),out)&&exact(out,want));
        const auto reject=[&](Bytes bad){signRange(bad,20,read32(valid,12));sign(bad);auto owner=std::make_shared<CodecAliasState>();if(want.sound.personalities)owner->instances=want.sound.personalities->instances;owner->wire.replaceAll(bad.data(),bad.size());out=want;out.sound.personalities=owner;const auto before=out;std::weak_ptr<CodecAliasState> weak=owner;const auto* input=owner->wire.getData();owner.reset();CHECK(!decodeProjectState(input,bad.size(),out)&&exact(out,before)&&!weak.expired());};
        for(std::size_t slot:{std::size_t(0),std::size_t(7)})for(unsigned revision:{0,2,255}){auto bad=valid;bad[20+currentSoundNumericBytes+20+effectBankCount*slot+11]=std::uint8_t(revision);reject(bad);}auto bad=valid;put(bad,4,11,2);reject(bad);bad=valid;put(bad,20+20+8*1078,0x7fc00000U,4);reject(bad);
        juce::MemoryBlock opaque;CHECK(encodeProjectState(want,opaque));out={};CHECK(decodeProjectState(opaque.getData(),opaque.getSize(),out)&&exact(out,want));
    }
}

void frequency_shift_old_project11_evidence()
{
    begin("frequency_shift_old_project11_evidence");
    const auto directory=juce::SystemStats::getEnvironmentVariable("AIRACK_FREQUENCY_SHIFT_OLD_PROJECT_EVIDENCE",{});
    if(directory.isEmpty())return;
    const juce::File folder(directory);const auto directoryReady=folder.createDirectory().wasOk();CHECK(directoryReady);if(!directoryReady)return;const auto registry=parameterRegistry();
    ProjectDocument old;for(std::size_t i=0;i<1055;++i){if(registry[i].kind==ParameterKind::continuous)old.sound.values[i]=float((i*13)%71)/100;old.sound.controlLocks[i]=(i%17)==0;}
    for(std::size_t slot=0;slot<8;++slot)old.sound.compatibility.effects[slot][2]=static_cast<AlgorithmRevision>(1+slot%2);
    for(std::size_t i=0;i<8;++i)old.sound.macros[i]={registry[1023+i].stateKey,-.7f+.15f*float(i)};
    CHECK(validateProjectDocument(old));const auto file=folder.getChildFile("old-project11-nonuniform-inactive-dimension-stereo-flanger-phaser-chorus-filter-eq-reverb2.projectstate");
    if(!file.existsAsFile()){juce::MemoryBlock bytes;CHECK(parameterCount==1055&&encodeProjectState(old,bytes));CHECK(file.replaceWithData(bytes.getData(),bytes.getSize()));}
    juce::MemoryBlock bytes;ProjectDocument recalled;CHECK(file.loadFileAsData(bytes));CHECK(decodeProjectState(bytes.getData(),bytes.getSize(),recalled));
    for(std::size_t i=0;i<1055;++i)CHECK(recalled.sound.values[i]==old.sound.values[i]&&recalled.sound.controlLocks[i]==old.sound.controlLocks[i]);
    CHECK(recalled==old);
}
void convolution_old_project12_evidence()
{
    begin("convolution_old_project12_evidence");
    const auto directory=juce::SystemStats::getEnvironmentVariable("AIRACK_CONVOLUTION_OLD_PROJECT_EVIDENCE",{});
    if(directory.isEmpty())return;
    const juce::File folder(directory);const auto directoryReady=folder.createDirectory().wasOk();CHECK(directoryReady);if(!directoryReady)return;const auto registry=parameterRegistry();
    ProjectDocument old;for(std::size_t i=0;i<1079;++i){if(registry[i].kind==ParameterKind::continuous)old.sound.values[i]=float((i*13)%71)/100;old.sound.controlLocks[i]=(i%17)==0;}
    for(std::size_t slot=0;slot<8;++slot)old.sound.compatibility.effects[slot][2]=static_cast<AlgorithmRevision>(1+slot%2);
    for(std::size_t i=0;i<8;++i)old.sound.macros[i]={registry[1055+i].stateKey,-.7f+.15f*float(i)};
    CHECK(validateProjectDocument(old));const auto file=folder.getChildFile("old-project12-nonuniform-inactive-frequency-shift-dimension-stereo-flanger-phaser-chorus-filter-eq-reverb2.projectstate");
    if(!file.existsAsFile()){juce::MemoryBlock bytes;const bool encoded=parameterCount==1079&&encodeProjectState(old,bytes);CHECK(encoded);if(!encoded)return;CHECK(file.replaceWithData(bytes.getData(),bytes.getSize()));}
    juce::MemoryBlock bytes;ProjectDocument recalled;CHECK(file.loadFileAsData(bytes));CHECK(decodeProjectState(bytes.getData(),bytes.getSize(),recalled));
    for(std::size_t i=0;i<1079;++i)CHECK(recalled.sound.values[i]==old.sound.values[i]&&recalled.sound.controlLocks[i]==old.sound.controlLocks[i]);
    CHECK(recalled==old);
}
