void frequency_split_project_migration_recall_and_atomic_rejection()
{
    begin("frequency_split_project_migration_recall_and_atomic_rejection");
    const auto captured=capturedFrequencySplitOldProject13();const auto native=bytes(captured);ProjectDocument migrated;
    CHECK(native[4]==13&&native[24]==14&&read32(native,28)==1111&&native.size()==10437);
    const bool decoded=decodeProjectState(captured.getData(),captured.getSize(),migrated);CHECK(decoded);if(!decoded)return;
    const auto defaults=defaultParameterValues();for(std::size_t i=0;i<1111;++i)CHECK(std::bit_cast<std::uint32_t>(migrated.sound.values[i])==read32(native,40+8*i)&&migrated.sound.controlLocks[i]==(native[20+9046+i]!=0));
    for(std::size_t i=1111;i<1231;++i)CHECK(migrated.sound.values[i]==defaults[i]&&!migrated.sound.controlLocks[i]);
    for(std::size_t slot=0;slot<8;++slot){for(std::size_t bank=0;bank<13;++bank)CHECK(migrated.sound.compatibility.effects[slot][bank]==native[20+10189+13*slot+bank]);CHECK(migrated.sound.compatibility.effects[slot][13]==1);}
    ProjectDocument opaque;CHECK(decodeProjectState(native.data()+20,10329,opaque)&&exact(opaque,migrated));
    juce::MemoryBlock saved;CHECK(encodeProjectState(migrated,saved));const auto upgraded=bytes(saved);CHECK(upgraded[4]==currentProjectStateVersion&&upgraded[24]==currentSoundStateVersion&&read32(upgraded,28)==4519&&upgraded.size()==41161);
    ProjectDocument out;CHECK(decodeProjectState(saved.getData(),saved.getSize(),out)&&exact(out,migrated));
    // Project the exact 13-bank logical predecessor from the actual new bases.
    // Both endpoints use the new row start; the old width is deliberately 13.
    const auto currentSound=Bytes(upgraded.begin()+20,upgraded.begin()+20+read32(upgraded,12));
    CHECK(currentSound.size()==41053&&read32(currentSound,4)==currentSoundStateVersion&&read32(currentSound,8)==4519);
    Bytes projected(currentSound.begin(),currentSound.begin()+16+8*1111);
    const auto currentLayout=16+8*parameterCount;
    projected.insert(projected.end(),currentSound.begin()+currentLayout,currentSound.begin()+currentLayout+78+64+1111);
    projected.insert(projected.end(),currentSound.begin()+currentSoundNumericBytes-12,currentSound.begin()+currentSoundNumericBytes);
    CHECK(projected.size()==10169);put(projected,4,14,4);put(projected,8,1111,4);
    const std::array<std::uint8_t,12> oldHeader{120,0,0,0,1,0,4,2,8,13,0,0};projected.insert(projected.end(),oldHeader.begin(),oldHeader.end());
    projected.insert(projected.end(),currentSound.begin()+currentSoundNumericBytes+12,currentSound.begin()+currentSoundNumericBytes+20);
    for(std::size_t slot=0;slot<8;++slot){const auto start=currentSoundNumericBytes+20+effectBankCount*slot;projected.insert(projected.end(),currentSound.begin()+start,currentSound.begin()+start+13);}
    {const auto section=originalPersonalitySection(currentSound);projected.insert(projected.end(),section.begin(),section.end());}projected.resize(projected.size()+32);sign(projected);
    CHECK(projected==Bytes(native.begin()+20,native.begin()+20+10329));
    CHECK(envelope(projected,literalPatternFor(migrated.pattern),static_cast<std::uint8_t>(migrated.mode))==native);
    const auto rejectOld=[&](Bytes bad){sign(bad);out=migrated;CHECK(!decodeProjectState(bad.data(),bad.size(),out)&&exact(out,migrated));};
    for(unsigned version:{12,14,255}){auto bad=native;put(bad,4,version,2);rejectOld(bad);}
    auto bad=native;put(bad,36,parameterRegistry()[1111].stateKey,4);signRange(bad,20,10329);rejectOld(bad);
    for(int quality:{0,1})for(bool group:{false,true})for(bool embedded:{false,true}){
        auto source=rich();source.sound.values[758]=float(quality);source.group=group?grouped().group:std::optional<GroupIntent>{};
        CHECK(editRackLayout(source.sound.layout,{RackEditKind::addEffect,0,masterChain,0,EffectKind::frequencySplit},source.sound.layout)==RackEditResult::applied);
        for(std::size_t slot=0;slot<8;++slot)for(std::size_t field=0;field<8;++field){const auto i=1111+8*slot+field;source.sound.values[i]=(field==2||field==5)?float((field+slot)%2):.14f+.08f*float((slot+field)%8);source.sound.controlLocks[i]=(slot+field)%2==0;}
        RackInstance instance;instance.design.name="Frequency Split retained75";instance.design.role=RackRole::fx;instance.design.panel.sections={"Bands"};instance.design.units={{0,NativeModule::frequencySplit,{}}};instance.bindings={{0,0}};
        for(std::size_t i=0;i<dynamicEqParameterStart;++i)if(parameterRegistry()[i].id.startsWith("effect.1."))instance.design.units[0].defaults.push_back({0,parameterRegistry()[i].id.substring(9),source.sound.values[i]});CHECK(instance.design.units[0].defaults.size()==82);
        instance.design.panel.controls={{"Crossover",0,0,"frequency_split.crossover_hz",FocusWidget::rotary,FocusResponse::logarithmic,20,20000}};
        if(embedded){auto state=std::make_shared<RackPersonalityState>();state->instances={instance};source.sound.personalities=state;}
        juce::MemoryBlock current;const bool encoded=encodeProjectState(source,current);CHECK(encoded);if(!encoded)continue;const auto valid=bytes(current);CHECK(valid[4]==currentProjectStateVersion&&valid[24]==currentSoundStateVersion&&read32(valid,28)==4519);CHECK(decodeProjectState(current.getData(),current.getSize(),out)&&exact(out,source));
        const auto reject=[&](Bytes changed){signRange(changed,20,read32(changed,12));sign(changed);out=source;CHECK(!decodeProjectState(changed.data(),changed.size(),out)&&exact(out,source));};
        auto changed=valid;put(changed,4,13,2);reject(changed);changed=valid;put(changed,4,255,2);reject(changed);
        for(std::size_t slot:{std::size_t(0),std::size_t(7)}){changed=valid;changed[20+currentSoundNumericBytes+20+effectBankCount*slot+13]=255;reject(changed);}
        changed=valid;put(changed,20+20+8*1174,0x7fc00000U,4);reject(changed);
        struct Alias:RackPersonalityState{juce::MemoryBlock wire;};auto owner=std::make_shared<Alias>();owner->wire=current;changed=valid;changed.back()^=1;owner->wire.replaceAll(changed.data(),changed.size());auto alias=source;alias.sound.personalities=owner;const auto* input=owner->wire.getData();std::weak_ptr<Alias> weak=owner;owner.reset();CHECK(!decodeProjectState(input,changed.size(),alias)&&!weak.expired()&&alias.sound.personalities==weak.lock());
    }
}

void mid_side_split_old_project14_evidence()
{
    begin("mid_side_split_old_project14_evidence");
    const auto directory=juce::SystemStats::getEnvironmentVariable("AIRACK_MID_SIDE_SPLIT_OLD_PROJECT_EVIDENCE",{});
    if(directory.isEmpty())return;
    const juce::File folder(directory);const auto directoryReady=folder.createDirectory().wasOk();CHECK(directoryReady);if(!directoryReady)return;const auto registry=parameterRegistry();
    ProjectDocument old;for(std::size_t i=0;i<1175;++i){if(registry[i].kind==ParameterKind::continuous)old.sound.values[i]=float((i*13)%71)/100;old.sound.controlLocks[i]=(i%17)==0;}
    for(std::size_t slot=0;slot<8;++slot)old.sound.compatibility.effects[slot][2]=static_cast<AlgorithmRevision>(1+slot%2);
    for(std::size_t i=0;i<8;++i){const std::array<std::size_t,6> fields{{0,1,3,4,6,7}};const auto target=1111+8*(i/6)+fields[i%6];CHECK(registry[target].kind==ParameterKind::continuous);old.sound.macros[i]={registry[target].stateKey,-.7f+.15f*float(i)};}
    CHECK(validateProjectDocument(old));const auto file=folder.getChildFile("old-project14-nonuniform-inactive-all-fx.projectstate");
    if(!file.existsAsFile()){juce::MemoryBlock bytes;const bool encoded=parameterCount==1175&&encodeProjectState(old,bytes);CHECK(encoded);if(!encoded)return;CHECK(file.replaceWithData(bytes.getData(),bytes.getSize()));}
    juce::MemoryBlock bytes;ProjectDocument recalled;CHECK(file.loadFileAsData(bytes));CHECK(decodeProjectState(bytes.getData(),bytes.getSize(),recalled));
    for(std::size_t i=0;i<1175;++i)CHECK(recalled.sound.values[i]==old.sound.values[i]&&recalled.sound.controlLocks[i]==old.sound.controlLocks[i]);
    CHECK(recalled==old);
}
