void shape_extension_project19_and_frozen_project18()
{
    begin("shape_extension_project19_and_frozen_project18");
    CHECK(currentProjectStateVersion==30&&currentMinimumProjectStateBytes==41161&&maximumProjectStateBytes==835738);
    const auto raw=load("tests/fixtures/eq-shapes-legacy/rich-v18.airackproject",18669,"83005ca697c73e21defb0d844e9b759e9a3797b1850968d4c3a8e279eae91a98");
    ProjectDocument old;CHECK(decodeProjectState(raw.getData(),raw.getSize(),old));
    const SoundDocument defaults;for(std::size_t i=2023;i<parameterCount;++i)CHECK(old.sound.values[i]==defaults.values[i]&&!old.sound.controlLocks[i]);
    juce::MemoryBlock upgraded;CHECK(encodeProjectState(old,upgraded));juce::MemoryInputStream header(upgraded,false);header.skipNextBytes(4);CHECK(header.readShort()==currentProjectStateVersion);
    ProjectDocument recalled;CHECK(decodeProjectState(upgraded.getData(),upgraded.getSize(),recalled)&&recalled==old);
    if(parameterCount<2191)return;
    for(int selection=0;selection<5;++selection){
        ProjectDocument project;for(std::size_t i=dynamicEqExtensionParameterStart;i<delayStereoParameterStart;++i){const int count=int(parameterRegistry()[i].choices.size());project.sound.values[i]=float(selection%count)/float(count-1);project.sound.controlLocks[i]=i%2==1;}
        juce::MemoryBlock encoded;CHECK(encodeProjectState(project,encoded));CHECK(encoded.getSize()==41161);CHECK(decodeProjectState(encoded.getData(),encoded.getSize(),recalled)&&recalled==project);
    }
}
