    if(juce::SystemStats::getEnvironmentVariable("AIRACK_FREQUENCY_SHIFT_OLD_PROJECT_EVIDENCE",{}).isNotEmpty()){frequency_shift_old_project11_evidence();std::cout<<"Native oldProject11 checks="<<checks<<" failures="<<failures<<'\n';return failures?1:0;}
    if(juce::SystemStats::getEnvironmentVariable("AIRACK_DIMENSION_OLD_PROJECT_EVIDENCE",{}).isNotEmpty()){dimension_old_project10_evidence();std::cout<<"Native oldProject10 checks="<<checks<<" failures="<<failures<<'\n';return failures?1:0;}
    if(juce::SystemStats::getEnvironmentVariable("AIRACK_STEREO_OLD_PROJECT_EVIDENCE",{}).isNotEmpty()){stereo_old_project9_evidence();std::cout<<"Native oldProject9 checks="<<checks<<" failures="<<failures<<'\n';return failures?1:0;}
    if(juce::SystemStats::getEnvironmentVariable("AIRACK_FLANGER_OLD_PROJECT_EVIDENCE",{}).isNotEmpty()){flanger_old_project8_evidence();std::cout<<"Native oldProject8 checks="<<checks<<" failures="<<failures<<'\n';return failures?1:0;}
    if(juce::SystemStats::getEnvironmentVariable("AIRACK_PHASER_OLD_PROJECT_EVIDENCE",{}).isNotEmpty()){phaser_old_project7_evidence();std::cout<<"Native oldProject7 checks="<<checks<<" failures="<<failures<<'\n';return failures?1:0;}
    if(juce::SystemStats::getEnvironmentVariable("AIRACK_CHORUS_OLD_PROJECT_EVIDENCE",{}).isNotEmpty()){chorus_old_project6_evidence();std::cout<<"Native oldProject6 checks="<<checks<<" failures="<<failures<<'\n';return failures?1:0;}
    begin("algorithm_revision_transaction: explicit current project format");
    juce::MemoryBlock compatibilityWire;CHECK(airack::encodeProjectState(airack::ProjectDocument{},compatibilityWire));
    const auto* compatibilityBytes=static_cast<const unsigned char*>(compatibilityWire.getData());
    CHECK(compatibilityWire.getSize()>6&&compatibilityBytes[4]==currentProjectStateVersion&&compatibilityBytes[5]==0);
    mid_side_project_migration_recall_and_atomic_rejection();
    frequency_split_project_migration_recall_and_atomic_rejection();
    legacy_envelope_dispatch();
    old_project4_migration_and_version_rejection();
    old_project5_migration_and_domain_rejection();
    old_project6_migration_and_domain_rejection();
    old_project10_migration_and_domain_rejection();    convolution_project_migration_recall_and_atomic_rejection();
frequency_shift_project_migration_recall_and_atomic_rejection();dimension_project_recall_and_atomic_rejection();
    old_project9_migration_and_domain_rejection();stereo_project_recall_and_atomic_rejection();
